use vstd::prelude::*;

verus! {

    /// Given a non‐empty vector of f32’s, return a vector of the same length
    /// whose first and last entries are 0.5 and whose interior entries are 1.0.
    fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
        requires
            x.len() > 0,
        ensures
            result.len() == x.len(),
        ensures
            // for every index i, if it's an endpoint then 0.5, otherwise 1.0
            forall |i: usize| i < x.len() ==>
                result[i] == if i == 0 || i == x.len() - 1 { 0.5 } else { 1.0 },
    {
        let n = x.len();
        // We'll build up `result` by pushing one weight at a time.
        let mut result: Vec<f32> = Vec::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant
                // loop index never exceeds length
                i <= n,
                // result has exactly i entries so far
                result.len() == i,
                // for every j < i, result[j] was chosen correctly
                forall |j: usize| j < i ==>
                    result[j] == if j == 0 || j == n - 1 { 0.5 } else { 1.0 },
        {
            // choose the weight at position i
            let w: f32 = if i == 0 || i == n - 1 {
                0.5
            } else {
                1.0
            };
            result.push(w);
            i += 1;
        }
        result
    }

}

fn main() {
    // Example usage (unverified):
    let v = vec![3.0_f32, 7.0, 9.0, 2.0];
    let w = chebweight(v);
    assert!(w == vec![0.5, 1.0, 1.0, 0.5]);
}